import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Έλεγχος αναθέσεων στην έναρξη βάρδιας","description":"","frontmatter":{},"headers":[],"relativePath":"el/tutorials/start-of-shift.md","filePath":"el/tutorials/start-of-shift.md"}'),o={name:"el/tutorials/start-of-shift.md"};function i(s,a,n,h,c,d){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="ελεγχος-αναθεσεων-στην-εναρξη-βαρδιας" tabindex="-1">Έλεγχος αναθέσεων στην έναρξη βάρδιας <a class="header-anchor" href="#ελεγχος-αναθεσεων-στην-εναρξη-βαρδιας" aria-label="Permalink to &quot;Έλεγχος αναθέσεων στην έναρξη βάρδιας&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Εκπαιδευτικό προσχέδιο βάσει πηγαίου κώδικα · TransferBook+ v0.7.9. Επιβεβαιώστε έκδοση, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα. Δεν τεκμαίρεται ζωντανή ενεργοποίηση.</p></div><h2 id="σεναριο-εκπαιδευσης" tabindex="-1">Σενάριο εκπαίδευσης <a class="header-anchor" href="#σεναριο-εκπαιδευσης" aria-label="Permalink to &quot;Σενάριο εκπαίδευσης&quot;">​</a></h2><p>Ο υπεύθυνος αναθέσεων προετοιμάζει τις αφίξεις και αναχωρήσεις της ημέρας. Χρησιμοποιήστε το εξουσιοδοτημένο εταιρικό περιβάλλον και εγκεκριμένα δοκιμαστικά δεδομένα.</p><h2 id="βηματα" tabindex="-1">Βήματα <a class="header-anchor" href="#βηματα" aria-label="Permalink to &quot;Βήματα&quot;">​</a></h2><ol><li>Ανοίξτε το Command Center και εξετάστε τις εκκρεμότητες και τις επερχόμενες αφίξεις αεροδρομίων και λιμανιών.</li><li>Στο ημερολόγιο αναθέσεων επιλέξτε Day, σωστή ημερομηνία και περιοχή. Αρχικά δείτε όλες τις καταστάσεις, κατόπιν φιλτράρετε εκκρεμείς αναθέσεις ή προσφορές.</li><li>Εντοπίστε κρατήσεις χωρίς ανάθεση και όσες απαιτούν προσφορά ή αποδοχή εκδρομής. Επιλύστε τις εμπορικές εκκρεμότητες πριν την ανάθεση.</li><li>Ελέγξτε διαθεσιμότητα και βάρδιες οδηγών, κατάσταση και συντήρηση οχημάτων. Εξετάστε χωρητικότητα και επικαλύψεις μαζί με το ρυθμισμένο χρονικό περιθώριο.</li><li>Επαληθεύστε κάθε αποθηκευμένη ανάθεση και επανελέγξτε τις εκκρεμότητες. Ενημερώστε τον αρμόδιο χειριστή για όσα δεν επιλύθηκαν μέσω εγκεκριμένων καναλιών.</li></ol><h2 id="αναμενομενο-αποτελεσμα" tabindex="-1">Αναμενόμενο αποτέλεσμα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα&quot;">​</a></h2><p>Ελεγμένο πρόγραμμα με σαφή ευθύνη για τις εκκρεμότητες. Ο πίνακας δεν αποδεικνύει ζωντανό GPS ή είσπραξη πληρωμών.</p><p>Δείτε <a href="/el/plus/command-center.html">Command Center</a>, <a href="/el/plus/drivers-and-rosters.html">Οδηγοί και βάρδιες</a> και <a href="/el/plus/vehicle-maintenance.html">Συντήρηση</a>.</p>',9)])])}const p=e(o,[["render",i]]);export{m as __pageData,p as default};
